import { warm } from '../earcon'
import type { Beat, Line, Note } from './script'

// Plays the call: voices in order, coaching landing on the glass at the
// moments the product would land it. Audio-driven, not clock-driven — a
// beat starts when the previous clip *ends*, so the HUD never runs ahead of
// the voice and a slow network only delays, never desyncs.

export interface Surface {
  subtitle(who: Line['who'] | null, text: string): void
  steer(label: string, why: string): void
  clearSteer(): void
  cue(text: string): void
  clearCue(): void
  /** The film's annotation beside the glass (script.ts `Note`). */
  note(note: Note): void
  clearNote(): void
}

export interface DirectorOptions {
  /** Called when coaching lands, for the product's earcon. */
  earcon?: (kind: 'steer' | 'cue') => void
}

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms))

// A note is read, not glanced. The film holds for it: the explanation lands
// first and sits alone long enough to read, then the coaching it explains
// lands, then the call goes on (Alexis, 2026-09-04: "make sure people have
// time to read that, and the explanation comes first").
// Slowed again 2026-09-05 ("moving too fast, I can't process what I'm
// reading" — three text areas were changing at once).
const NOTE_READ_MS = 3400
const NOTE_THEN_COACHING_MS = 1800
const STEER_RETIRE_MS = 3600
const CUE_DWELL_MS = 4500

/** If a clip fails to load, hold the subtitle for about as long as it would have taken to say. */
const estimateMs = (text: string) => 500 + text.length * 62

export class Director {
  private clips = new Map<string, HTMLAudioElement>()
  private stopped = false
  // Bumped by every play(); a loop from an earlier run that wakes from a
  // sleep after stop()+play() sees a stale token and exits instead of
  // running alongside the new one.
  private run = 0
  private timers: ReturnType<typeof setTimeout>[] = []
  private steerOnStage = false

  constructor(
    private readonly beats: Beat[],
    private readonly surface: Surface,
    private readonly opts: DirectorOptions = {},
  ) {}

  /** Start fetching every clip now, so playback never waits on the network mid-call. */
  preload(): void {
    for (const beat of this.beats) {
      if (beat.kind !== 'line' || this.clips.has(beat.line.audio)) continue
      const a = new Audio(beat.line.audio)
      a.preload = 'auto'
      this.clips.set(beat.line.audio, a)
    }
  }

  /**
   * Call synchronously inside the start click. iOS Safari refuses `play()`
   * on any media element that hasn't played once during a user gesture, so
   * every clip gets a silent play-and-pause now, before any `await`.
   */
  unlock(): void {
    this.preload()
    for (const a of this.clips.values()) warm(a)
  }

  async play(): Promise<void> {
    this.stopped = false
    const mine = ++this.run
    const dead = () => this.stopped || mine !== this.run
    for (const beat of this.beats) {
      if (dead()) return
      if (beat.kind === 'pause') {
        await sleep(beat.ms)
        continue
      }
      if (beat.kind === 'steer') {
        if (beat.note) {
          // Explanation first, alone, for as long as it takes to read.
          this.surface.note(beat.note)
          await sleep(NOTE_READ_MS)
          if (dead()) return
        }
        this.surface.steer(beat.label, beat.why)
        this.steerOnStage = true
        this.opts.earcon?.('steer')
        // Then the coaching gets its own beat before the reply starts.
        if (beat.note) await sleep(NOTE_THEN_COACHING_MS)
        continue
      }
      await this.speak(beat.line, dead)
    }
  }

  stop(): void {
    this.stopped = true
    for (const t of this.timers) clearTimeout(t)
    this.timers = []
    for (const a of this.clips.values()) {
      a.pause()
      a.currentTime = 0
    }
    this.surface.subtitle(null, '')
    this.surface.clearSteer()
    this.surface.clearCue()
    this.surface.clearNote()
    this.steerOnStage = false
  }

  private async speak(line: Line, dead: () => boolean): Promise<void> {
    this.surface.subtitle(line.who, line.text)

    // A steer that's on stage retires shortly after you act on it. The real
    // glass holds a card ~6 s (WEARABLE_AR §8); here the point is made the
    // moment the reply starts, and the eye should go back to her.
    if (line.who === 'you' && this.steerOnStage) {
      this.later(STEER_RETIRE_MS, () => {
        this.surface.clearSteer()
        this.steerOnStage = false
      })
      // The steer's annotation outlives the steer a little — it's the one
      // sentence in the film that says what you just saw.
      this.later(STEER_RETIRE_MS + 1200, () => this.surface.clearNote())
    }
    const clip = this.clips.get(line.audio) ?? new Audio(line.audio)
    if (line.cue) {
      // A cue lands mid-sentence and the voice keeps going — it is never
      // interrupted (Alexis, 2026-09-06).
      const { text, atMs } = line.cue
      this.later(atMs, () => {
        this.surface.cue(text)
        this.opts.earcon?.('cue')
        this.later(CUE_DWELL_MS, () => this.surface.clearCue())
      })
    }

    // With no audio, the subtitle holds for the spoken estimate, so the
    // scene paces the same either way.
    await this.playClip(clip, estimateMs(line.text))
    if (dead()) return
    await sleep(650)
    if (dead()) return
    this.surface.subtitle(null, '')
  }

  private later(ms: number, fn: () => void): void {
    const t = setTimeout(() => {
      if (!this.stopped) fn()
    }, ms)
    this.timers.push(t)
  }

  private playClip(a: HTMLAudioElement, fallbackMs: number): Promise<void> {
    return new Promise((resolve) => {
      let done = false
      const finish = () => {
        if (done) return
        done = true
        a.removeEventListener('ended', finish)
        a.removeEventListener('error', onError)
        resolve()
      }
      const onError = () => {
        // No audio (blocked CDN, missing file) — keep the subtitle up for
        // roughly the spoken duration so the scene still reads.
        setTimeout(finish, fallbackMs)
      }
      a.addEventListener('ended', finish)
      a.addEventListener('error', onError)
      a.currentTime = 0
      a.play().catch(onError)
      // Belt and braces: a clip that never fires `ended` must not hang the call.
      setTimeout(finish, fallbackMs * 3)
    })
  }
}
