export interface Line {
  who: 'you' | 'them'
  text: string
  audio: string
  /** A live cue that fires while this line is being spoken. */
  cue?: { text: string; atMs: number }
}

/**
 * The film's own annotation — NOT on the glass. Used once, under the first
 * steer, to say in plain words what the viewer is looking at: TalkPilot,
 * live. It lands first, alone, then the steer lands above it (Alexis,
 * 2026-09-06: one place to look, short enough to read at a glance; the
 * cue's note is gone — the voice is never interrupted).
 */
export interface Note {
  eyebrow: string
  text: string
}

export type Beat =
  | { kind: 'line'; line: Line }
  | { kind: 'steer'; label: string; why: string; note?: Note }
  | { kind: 'pause'; ms: number }

const you = (text: string, audio: string, cue?: Line['cue']): Beat => ({ kind: 'line', line: { who: 'you', text, audio: `${CDN}${audio}`, cue } })
const them = (text: string, audio: string): Beat => ({ kind: 'line', line: { who: 'them', text, audio: `${CDN}${audio}` } })
const steer = (label: string, why: string, note?: Note): Beat => ({ kind: 'steer', label, why, note })
const pause = (ms: number): Beat => ({ kind: 'pause', ms })

