import { bindDeviceToggles, DEVICE_NAME, deviceToggleHtml, resolveDevice } from '../device'
import { createEarcon } from '../earcon'
import { Director, type Surface } from './director'
import { BEATS, PORTRAIT, SCENE, type Line } from './script'

// The film. One scene, first person: Diane across the table, the TalkPilot
// HUD in your vision, the call playing out. Two moments of interaction and
// no more — a start (browsers won't play sound without a click; it's the
// "put on the glasses" beat, not a control) and a replay at the end.
//
// What's on the glass is exactly what the product puts there: the short
// steer and its why, a live cue, and the LIVE · mode footer — nothing else
// (WEARABLE_AR §8, product call 2026-09-03). The subtitles are the film's,
// not the glasses' — they sit at the bottom like any subtitle, so a viewer
// on mute still follows the call. So is the note under the glass text: it
// appears once, under the first steer, to say what the viewer is looking
// at — TalkPilot, live — and then never again (Alexis, 2026-09-04/06).

const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches
const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms))

const device = resolveDevice()
// `?still=1` opens straight on the glass with the first steer up and no
// sound — a stable frame for screenshots and side-by-side comparisons.
const still = new URLSearchParams(location.search).get('still') === '1'

const root = document.getElementById('stage')!
root.className = 'film'
root.innerHTML = `
  <div class="scene" aria-hidden="true">
    <div class="photo-fallback"></div>
    <img class="photo" alt="" decoding="async" />
    <div class="grade"></div>
    <div class="lens"></div>
    <div class="frame"></div>
    <div class="hud">
      <div class="hud-boot">TalkPilot</div>
      <div class="hud-steer" hidden>
        <img class="hud-brand" src="${import.meta.env.BASE_URL}brand/talkpilot.png" alt="" />
        <div class="hud-label"></div>
        <div class="hud-why"></div>
      </div>
      <div class="hud-cue" hidden><img class="hud-brand" src="${import.meta.env.BASE_URL}brand/talkpilot.png" alt="" /><span class="hud-cue-text"></span></div>
      <div class="hud-status"></div>
      <div class="note" hidden>
        <span class="note-eyebrow"></span>
        <span class="note-text"></span>
      </div>
    </div>
    <div class="subtitle" hidden>
      <span class="sub-who"></span>
      <span class="sub-text"></span>
    </div>
  </div>

  <section class="overlay intro">
    <p class="eyebrow">TalkPilot × <span class="device-name">${DEVICE_NAME[device]}</span></p>
    <h1>Your next conversation,<br /><em>through the glasses.</em></h1>
    <p class="lede">Ninety seconds. Sound on.</p>
    ${deviceToggleHtml(device)}
    <button class="cta" type="button">Put on the glasses</button>
    <p class="meta">${SCENE.name} · ${SCENE.role} · Q3 renewal</p>
  </section>

  <section class="overlay brief" hidden>
    <p class="eyebrow">Before you watch</p>
    <ul class="brief-lines">
      <li>TalkPilot listens to the conversation you are already having.</li>
      <li>When the other person finishes a thought, one line appears on your glasses.</li>
      <li>They see nothing. Nothing is said out loud.</li>
    </ul>
    <p class="meta">What follows is one call, from your point of view.<br />${SCENE.name} · ${SCENE.role}</p>
  </section>

  <section class="overlay outro" hidden>
    <p class="eyebrow">That was TalkPilot</p>
    <h1><em>It coached the whole conversation.</em><br />Nobody saw it.</h1>
    <p class="lede">Three steers and one cue, each in the corner of your eye, each gone before she'd notice you'd looked.</p>
    <button class="cta" type="button">Watch again</button>
    <a class="link" href="./live.html" hidden>Try it live with your own iPhone →</a>
  </section>
`

const $ = <T extends HTMLElement>(sel: string): T => root.querySelector<T>(sel)!
const photo = $<HTMLImageElement>('.photo')
const intro = $<HTMLElement>('.intro')
const brief = $<HTMLElement>('.brief')
const outro = $<HTMLElement>('.outro')
const steerEl = $<HTMLElement>('.hud-steer')
const labelEl = $<HTMLElement>('.hud-label')
const whyEl = $<HTMLElement>('.hud-why')
const cueEl = $<HTMLElement>('.hud-cue')
const cueText = $<HTMLElement>('.hud-cue-text')
const statusEl = $<HTMLElement>('.hud-status')
const noteEl = $<HTMLElement>('.note')
const noteEyebrow = $<HTMLElement>('.note-eyebrow')
const noteText = $<HTMLElement>('.note-text')
const subEl = $<HTMLElement>('.subtitle')
const subWho = $<HTMLElement>('.sub-who')
const subText = $<HTMLElement>('.sub-text')

// MARK: - Portrait

photo.addEventListener('error', () => root.classList.add('no-photo'))
photo.addEventListener('load', () => root.classList.add('has-photo'))
photo.src = PORTRAIT.primary

// MARK: - Earcons (shared with the live page)

const earcon = createEarcon()

// MARK: - Surface: what the director is allowed to put on screen

const surface: Surface = {
  subtitle(who: Line['who'] | null, text: string) {
    if (!who) {
      subEl.classList.remove('show')
      return
    }
    subWho.textContent = who === 'you' ? 'You' : SCENE.name.split(' ')[0] ?? ''
    subText.textContent = text
    subEl.dataset.who = who
    subEl.hidden = false
    // restart the transition
    subEl.classList.remove('show')
    void subEl.offsetWidth
    subEl.classList.add('show')
  },
  steer(label, why) {
    labelEl.textContent = label
    whyEl.textContent = why
    steerEl.hidden = false
    steerEl.classList.remove('show')
    void steerEl.offsetWidth
    steerEl.classList.add('show')
  },
  clearSteer() {
    steerEl.classList.remove('show')
  },
  cue(text) {
    cueText.textContent = text
    cueEl.hidden = false
    cueEl.classList.remove('show')
    void cueEl.offsetWidth
    cueEl.classList.add('show')
  },
  clearCue() {
    cueEl.classList.remove('show')
  },
  note({ eyebrow, text }) {
    noteEyebrow.textContent = eyebrow
    noteText.textContent = text
    noteEl.hidden = false
    noteEl.classList.remove('show')
    void noteEl.offsetWidth
    noteEl.classList.add('show')
  },
  clearNote() {
    noteEl.classList.remove('show')
  },
}

const director = new Director(BEATS, surface, { earcon: (kind) => earcon.play(kind) })
if (!still) director.preload()

// MARK: - Device: Even G2 (green projection) or Meta Ray-Ban Display (white cards)

bindDeviceToggles(root, device, (d) => {
  for (const el of root.querySelectorAll('.device-name')) el.textContent = DEVICE_NAME[d]
})

// MARK: - Status footer: "LIVE · Sales", no clock — like the real glass

// MARK: - Play

let run = 0

async function start(): Promise<void> {
  const mine = ++run
  // Everything media must be touched inside the click, before the first await.
  director.unlock()
  await earcon.unlock()

  outro.hidden = true
  intro.classList.add('gone')
  root.classList.remove('ended')
  root.classList.add('on')
  statusEl.textContent = ''

  // The "putting them on" beat: the lens closes in, the HUD wakes.
  await sleep(reduced ? 250 : 1500)
  if (mine !== run) return
  intro.hidden = true

  // Then say what this is, before anyone has to infer it from a sales call.
  // Held rather than clicked through: no more buttons (Alexis, 2026-09-04).
  brief.hidden = false
  await sleep(reduced ? 400 : 800)
  if (mine !== run) return
  brief.classList.add('reading')
  await sleep(reduced ? 600 : 7200)
  if (mine !== run) return
  brief.classList.add('gone')
  await sleep(reduced ? 100 : 700)
  if (mine !== run) return
  brief.hidden = true
  brief.classList.remove('reading', 'gone')

  statusEl.textContent = `LIVE · ${SCENE.mode}`

  await director.play()
  if (mine !== run) return

  statusEl.textContent = 'Call ended'
  await sleep(1700)
  if (mine !== run) return
  root.classList.add('ended')
  outro.hidden = false
}

function replay(): void {
  director.stop()
  root.classList.remove('on')
  intro.hidden = false
  intro.classList.remove('gone')
  brief.hidden = true
  brief.classList.remove('reading', 'gone')
  outro.hidden = true
  // Give the lens a frame to reopen before we close it again.
  requestAnimationFrame(() => void start())
}

intro.querySelector('.cta')!.addEventListener('click', () => void start())
outro.querySelector('.cta')!.addEventListener('click', replay)

if (still) {
  intro.hidden = true
  brief.hidden = true
  root.classList.add('on', 'still')
  statusEl.textContent = `LIVE · ${SCENE.mode}`
  const first = BEATS.find((b) => b.kind === 'steer')
  if (first && first.kind === 'steer') surface.steer(first.label, first.why)
}
